package com.farika.soundflow;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Durable metadata only. No access tokens, signed audio URLs or raw content keys. */
public final class SyncDb extends SQLiteOpenHelper {
 public SyncDb(Context c){super(c,"downloads.db",null,3);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE plans(owner TEXT,id TEXT,title TEXT,kind TEXT,auto INTEGER DEFAULT 0,active INTEGER DEFAULT 0,listed INTEGER DEFAULT 0,status TEXT DEFAULT 'В очереди',PRIMARY KEY(owner,id))");d.execSQL("CREATE TABLE items(owner TEXT,plan TEXT,tid TEXT,pos INTEGER,data TEXT,state TEXT,error TEXT,retryAt INTEGER DEFAULT 0,PRIMARY KEY(owner,plan,pos))");}
 public void onUpgrade(SQLiteDatabase d,int a,int b){if(a<2)d.execSQL("ALTER TABLE plans ADD COLUMN active INTEGER DEFAULT 0");if(a<3){d.execSQL("ALTER TABLE plans ADD COLUMN listed INTEGER DEFAULT 0");d.execSQL("UPDATE plans SET listed=1 WHERE EXISTS(SELECT 1 FROM items WHERE items.owner=plans.owner AND items.plan=plans.id)");}}
 public void ensure(String owner,String id,String title,String kind){ContentValues v=new ContentValues();v.put("owner",owner);v.put("id",id);v.put("title",title);v.put("kind",kind);getWritableDatabase().insertWithOnConflict("plans",null,v,SQLiteDatabase.CONFLICT_IGNORE);v=new ContentValues();v.put("title",title);v.put("kind",kind);getWritableDatabase().update("plans",v,"owner=? AND id=?",new String[]{owner,id});}
 public void auto(String owner,String id,boolean value){ContentValues v=new ContentValues();v.put("auto",value?1:0);getWritableDatabase().update("plans",v,"owner=? AND id=?",new String[]{owner,id});}
 public void status(String o,String id,String text){ContentValues v=new ContentValues();v.put("status",text);getWritableDatabase().update("plans",v,"owner=? AND id=?",new String[]{o,id});}
 public ArrayList<JSONObject> plans(String owner,boolean onlyAuto){ArrayList<JSONObject>a=new ArrayList<>();try(Cursor c=getReadableDatabase().query("plans",null,"owner=?"+(onlyAuto?" AND auto=1":""),new String[]{owner},null,null,"title COLLATE NOCASE")){while(c.moveToNext()){JSONObject j=new JSONObject();for(String k:new String[]{"owner","id","title","kind","status"})j.put(k,c.getString(c.getColumnIndexOrThrow(k)));j.put("auto",c.getInt(c.getColumnIndexOrThrow("auto"))==1);j.put("active",c.getInt(c.getColumnIndexOrThrow("active"))==1);j.put("listed",c.getInt(c.getColumnIndexOrThrow("listed"))==1);a.add(j);}}catch(JSONException ignored){}return a;}
 public void snapshot(String o,String p,List<Library.Track> tracks)throws Exception{SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{HashMap<String,Long> retries=new HashMap<>();HashMap<String,String> states=new HashMap<>(),errors=new HashMap<>();try(Cursor old=db.query("items",new String[]{"tid","retryAt","state","error"},"owner=? AND plan=?",new String[]{o,p},null,null,null)){while(old.moveToNext()){retries.put(old.getString(0),old.getLong(1));states.put(old.getString(0),old.getString(2));errors.put(old.getString(0),old.getString(3));}}db.delete("items","owner=? AND plan=?",new String[]{o,p});int i=0;for(Library.Track t:tracks){ContentValues v=new ContentValues();v.put("owner",o);v.put("plan",p);v.put("tid",t.id().isEmpty()?"missing:"+i:t.id());v.put("pos",i++);v.put("data",Library.json(t).toString());v.put("state",states.getOrDefault(t.id(),"PENDING"));v.put("error",errors.getOrDefault(t.id(),""));v.put("retryAt",retries.getOrDefault(t.id(),0L));db.insertOrThrow("items",null,v);}ContentValues known=new ContentValues();known.put("listed",1);db.update("plans",known,"owner=? AND id=?",new String[]{o,p});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public ArrayList<Library.Track> tracks(String o,String p){ArrayList<Library.Track>a=new ArrayList<>();try(Cursor c=getReadableDatabase().query("items",new String[]{"data"},"owner=? AND plan=?",new String[]{o,p},null,null,"pos")){while(c.moveToNext())try{a.add(Library.fromJson(new JSONObject(c.getString(0))));}catch(Exception ignored){}}return a;}
 public void state(String o,String p,String tid,String state,String error){ContentValues v=new ContentValues();v.put("state",state);v.put("error",error);getWritableDatabase().update("items",v,"owner=? AND plan=? AND tid=?",new String[]{o,p,tid});}
 public void sourceRemoved(String owner,String tid){ContentValues v=new ContentValues();v.put("state","REMOVED");v.put("error","");v.put("retryAt",0);getWritableDatabase().update("items",v,"owner=? AND tid=?",new String[]{owner,tid});}
 public void sourceReady(String owner,String tid){ContentValues v=new ContentValues();v.put("state","READY");v.put("error","");v.put("retryAt",0);getWritableDatabase().update("items",v,"owner=? AND tid=?",new String[]{owner,tid});}
 public long retryAt(String o,String p,String tid){try(Cursor c=getReadableDatabase().query("items",new String[]{"retryAt"},"owner=? AND plan=? AND tid=?",new String[]{o,p,tid},null,null,null)){return c.moveToFirst()?c.getLong(0):0;}}
 public void retry(String o,String p,String tid,long at){ContentValues v=new ContentValues();v.put("retryAt",at);getWritableDatabase().update("items",v,"owner=? AND plan=? AND tid=?",new String[]{o,p,tid});}
 public String counts(String o,String p){int total=0,ready=0,failed=0;try(Cursor c=getReadableDatabase().rawQuery("SELECT state,COUNT(*) FROM items WHERE owner=? AND plan=? GROUP BY state",new String[]{o,p})){while(c.moveToNext()){int n=c.getInt(1);total+=n;if("READY".equals(c.getString(0)))ready+=n;if("BLOCKED".equals(c.getString(0)))failed+=n;}}return ready+" / "+total+" сохранено"+(failed>0?" · недоступно: "+failed:"");}
 public ArrayList<JSONObject> failures(String o,String p){ArrayList<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query("items",new String[]{"tid","data","state","error"},"owner=? AND plan=? AND state IN ('BLOCKED','RETRY')",new String[]{o,p},null,null,"pos")){while(c.moveToNext())try{JSONObject data=new JSONObject(c.getString(1));out.add(new JSONObject().put("id",c.getString(0)).put("title",data.optString("title","Трек")).put("state",c.getString(2)).put("code",c.getString(3)));}catch(Exception ignored){}}return out;}
 public int[] totals(String o,String p){int[] n=new int[4];try(Cursor c=getReadableDatabase().rawQuery("SELECT state,COUNT(*) FROM items WHERE owner=? AND plan=? GROUP BY state",new String[]{o,p})){while(c.moveToNext()){int v=c.getInt(1);n[0]+=v;String state=c.getString(0);if("READY".equals(state))n[1]+=v;else if("BLOCKED".equals(state))n[2]+=v;else if(!"CANCELLED".equals(state)&&!"REMOVED".equals(state))n[3]+=v;}}return n;}
 public void cancelPending(String owner,String plan){ContentValues v=new ContentValues();v.put("state","CANCELLED");getWritableDatabase().update("items",v,"owner=? AND plan=? AND state IN ('PENDING','RUNNING')",new String[]{owner,plan});}
 public boolean cancelled(String owner,String plan,String tid){try(Cursor c=getReadableDatabase().query("items",new String[]{"state"},"owner=? AND plan=? AND tid=?",new String[]{owner,plan,tid},null,null,null)){return c.moveToFirst()&&"CANCELLED".equals(c.getString(0));}}
 public void active(String owner,String id,boolean value){ContentValues v=new ContentValues();v.put("active",value?1:0);getWritableDatabase().update("plans",v,"owner=? AND id=?",new String[]{owner,id});}
 public ArrayList<JSONObject> workPlans(String owner){ArrayList<JSONObject> out=new ArrayList<>();for(JSONObject plan:plans(owner,false)){int[] n=totals(owner,plan.optString("id"));if(plan.optBoolean("auto")||plan.optBoolean("active")||n[2]>0||n[3]>0)out.add(plan);}return out;}
 public long nextItemRetry(String owner,String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT MIN(retryAt) FROM items WHERE owner=? AND plan=? AND state NOT IN ('READY','CANCELLED','REMOVED') AND error<>'AUTH_401'",new String[]{owner,id})){return c.moveToFirst()&&!c.isNull(0)?c.getLong(0):Long.MAX_VALUE;}}
 public long nextAutomaticRetry(String owner){long at=Long.MAX_VALUE;for(JSONObject plan:workPlans(owner)){String id=plan.optString("id");try(Cursor c=getReadableDatabase().rawQuery("SELECT MIN(retryAt) FROM items WHERE owner=? AND plan=? AND state NOT IN ('READY','CANCELLED','REMOVED') AND error<>'AUTH_401'",new String[]{owner,id})){if(c.moveToFirst()&&!c.isNull(0))at=Math.min(at,Math.max(System.currentTimeMillis()+30000,c.getLong(0)));}if((plan.optBoolean("active")||plan.optBoolean("auto"))&&!plan.optBoolean("listed"))at=Math.min(at,System.currentTimeMillis()+30000);}return at==Long.MAX_VALUE?0:at;}
 public boolean otherReference(String owner,String plan,String tid){try(Cursor c=getReadableDatabase().rawQuery("SELECT 1 FROM items WHERE owner=? AND plan<>? AND tid=? LIMIT 1",new String[]{owner,plan,tid})){return c.moveToFirst();}}
 public void recoverInterrupted(String owner){ContentValues v=new ContentValues();v.put("state","PENDING");getWritableDatabase().update("items",v,"owner=? AND state='RUNNING'",new String[]{owner});}
 public void removePlan(String owner,String id){getWritableDatabase().delete("items","owner=? AND plan=?",new String[]{owner,id});getWritableDatabase().delete("plans","owner=? AND id=?",new String[]{owner,id});}
 public void clear(){getWritableDatabase().delete("items",null,null);getWritableDatabase().delete("plans",null,null);}
}
